export type JobType = "bash" | "task" | "eval";

export type JobStatus = "running" | "completed" | "failed" | "cancelled";

/** One background job this session owns. */
export interface JobSnapshot {
	id: string;
	type: JobType;
	status: JobStatus;
	/** Display label; a command cut to 120 characters. */
	label: string;
	startTime: number;
	/** Bytes the job has streamed so far (0 for jobs that never stream). */
	outputBytes: number;
	/** Running, quiet for a while, and its last line looks like a prompt. */
	waitingForInput: boolean;
	/** Full command line of a job that runs a process. */
	command?: string;
	endTime?: number;
	/** Exit status of a settled command. */
	exitCode?: number;
	/** Registry id of the subagent an async task job runs. */
	agentId?: string;
	lastOutputAt?: number;
}

/** Bounded read of a background job's output. */
export interface JobOutput {
	jobId: string;
	status: JobStatus;
	waitingForInput: boolean;
	/** Offset of `text`'s first byte. */
	fromByte: number;
	/** Pass as the next `fromByte` to read incrementally. */
	nextByte: number;
	/** Bytes the job has streamed so far. */
	totalBytes: number;
	/** Oldest byte the job still keeps. */
	startByte: number;
	/** Requested bytes no longer kept (older than `startByte`). */
	skippedBytes: number;
	/** `fromByte` was past the end; this read is the tail. */
	reset: boolean;
	/** The job does not stream: `text` is its latest text and replaces earlier reads. */
	snapshot: boolean;
	text: string;
}

